CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL) STRICT;
CREATE TABLE catalog_meta(id INTEGER PRIMARY KEY CHECK(id=1), db_instance_id TEXT NOT NULL, publication_seq INTEGER NOT NULL DEFAULT 0, schema_version INTEGER NOT NULL) STRICT;
CREATE TABLE sources(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('local-git','github')), name TEXT NOT NULL, settings TEXT NOT NULL) STRICT;
CREATE TABLE inventory_runs(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), state TEXT NOT NULL, scope TEXT NOT NULL, observed_at TEXT NOT NULL, reason TEXT) STRICT;
CREATE TABLE repositories(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), provider_host TEXT NOT NULL, provider_repo_id TEXT NOT NULL, name TEXT NOT NULL, url TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', current_snapshot TEXT, UNIQUE(provider_host,provider_repo_id)) STRICT;
CREATE TABLE repository_names(repo_id TEXT NOT NULL REFERENCES repositories(id), name TEXT NOT NULL, observed_at TEXT NOT NULL, PRIMARY KEY(repo_id,name)) STRICT;
CREATE TABLE jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, request TEXT NOT NULL, state TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 1, not_before REAL, checkpoint TEXT NOT NULL DEFAULT '{}', reason TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE INDEX jobs_ready ON jobs(state,not_before);
CREATE TABLE cache_entries(id TEXT PRIMARY KEY, repo_id TEXT NOT NULL REFERENCES repositories(id), generation INTEGER NOT NULL, path TEXT NOT NULL UNIQUE, state TEXT NOT NULL, last_used REAL NOT NULL, bytes INTEGER NOT NULL DEFAULT 0, UNIQUE(repo_id,generation)) STRICT;
CREATE TABLE cache_leases(cache_id TEXT NOT NULL REFERENCES cache_entries(id), job_id TEXT NOT NULL REFERENCES jobs(id), attempt INTEGER NOT NULL, acquired_at TEXT NOT NULL, PRIMARY KEY(cache_id,job_id)) STRICT;
CREATE TABLE space_reservations(job_id TEXT PRIMARY KEY REFERENCES jobs(id), reserved INTEGER NOT NULL CHECK(reserved>=0), consumed INTEGER NOT NULL CHECK(consumed>=0)) STRICT;
CREATE TABLE collection_runs(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), repo_id TEXT NOT NULL REFERENCES repositories(id), cache_id TEXT REFERENCES cache_entries(id), generation INTEGER NOT NULL, attempt INTEGER NOT NULL, state TEXT NOT NULL, started_at TEXT NOT NULL, refs_at TEXT, ended_at TEXT, object_format TEXT CHECK(object_format IN ('sha1','sha256')), kind TEXT NOT NULL DEFAULT 'git', roots_manifest TEXT, request TEXT NOT NULL DEFAULT '{}', UNIQUE(repo_id,generation,kind)) STRICT;
CREATE TABLE preservation_obligations(run_id TEXT PRIMARY KEY REFERENCES collection_runs(id), cache_id TEXT NOT NULL REFERENCES cache_entries(id), roots_fixed INTEGER NOT NULL DEFAULT 0, structure_done INTEGER NOT NULL DEFAULT 0, digest_done INTEGER NOT NULL DEFAULT 0, text_done INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE snapshots(id TEXT PRIMARY KEY, run_id TEXT NOT NULL UNIQUE REFERENCES collection_runs(id), repo_id TEXT NOT NULL REFERENCES repositories(id), generation INTEGER NOT NULL, published INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(repo_id,generation)) STRICT;
CREATE TABLE ref_observations(snapshot_id TEXT NOT NULL REFERENCES snapshots(id), raw_ref_name BLOB NOT NULL, kind TEXT NOT NULL, object_format TEXT NOT NULL, target_oid BLOB NOT NULL, peeled_oid BLOB, target_type TEXT, PRIMARY KEY(snapshot_id,raw_ref_name)) STRICT;
CREATE TABLE acquisition_roots(id INTEGER PRIMARY KEY, run_id TEXT NOT NULL REFERENCES collection_runs(id), repo_id TEXT NOT NULL REFERENCES repositories(id), object_format TEXT NOT NULL, oid BLOB NOT NULL, role TEXT NOT NULL, pr_number INTEGER, observation_id INTEGER, expected_oid TEXT, published INTEGER NOT NULL DEFAULT 0, UNIQUE(run_id,oid,role)) STRICT;
CREATE TABLE git_objects(id INTEGER PRIMARY KEY, object_format TEXT NOT NULL CHECK(object_format IN ('sha1','sha256')), oid BLOB NOT NULL CHECK((object_format='sha1' AND length(oid)=20) OR (object_format='sha256' AND length(oid)=32)), type TEXT NOT NULL CHECK(type IN ('commit','tree','blob','tag')), size INTEGER NOT NULL CHECK(size>=0), verified INTEGER NOT NULL DEFAULT 0, UNIQUE(object_format,oid)) STRICT;
CREATE TABLE repository_object_sources(repo_id TEXT NOT NULL REFERENCES repositories(id), object_id INTEGER NOT NULL REFERENCES git_objects(id), run_id TEXT NOT NULL REFERENCES collection_runs(id), PRIMARY KEY(repo_id,object_id,run_id)) STRICT;
CREATE TABLE commits(object_id INTEGER PRIMARY KEY REFERENCES git_objects(id), tree_id INTEGER NOT NULL REFERENCES git_objects(id), raw_headers BLOB NOT NULL, raw_message BLOB NOT NULL, metadata TEXT NOT NULL) STRICT;
CREATE TABLE commit_parents(commit_id INTEGER NOT NULL REFERENCES commits(object_id), parent_ordinal INTEGER NOT NULL CHECK(parent_ordinal>=0), parent_id INTEGER NOT NULL REFERENCES git_objects(id), PRIMARY KEY(commit_id,parent_ordinal)) STRICT;
CREATE INDEX parents_reverse ON commit_parents(parent_id,commit_id);
CREATE TABLE tree_entries(tree_id INTEGER NOT NULL REFERENCES git_objects(id), raw_name BLOB NOT NULL, mode INTEGER NOT NULL, child_format TEXT NOT NULL, child_oid BLOB NOT NULL, child_id INTEGER REFERENCES git_objects(id), PRIMARY KEY(tree_id,raw_name)) STRICT;
CREATE TABLE tag_objects(object_id INTEGER PRIMARY KEY REFERENCES git_objects(id), target_id INTEGER NOT NULL REFERENCES git_objects(id), raw_payload BLOB NOT NULL) STRICT;
CREATE TABLE contents(id INTEGER PRIMARY KEY, byte_length INTEGER NOT NULL CHECK(byte_length>=0), raw_text TEXT, text_state TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE content_digests(content_id INTEGER NOT NULL REFERENCES contents(id), representation TEXT NOT NULL, algorithm TEXT NOT NULL CHECK(algorithm IN ('md5','sha1','sha256')), digest BLOB NOT NULL CHECK((algorithm='md5' AND length(digest)=16) OR (algorithm='sha1' AND length(digest)=20) OR (algorithm='sha256' AND length(digest)=32)), verified_at TEXT NOT NULL, pipeline_version TEXT NOT NULL, PRIMARY KEY(content_id,representation,algorithm)) STRICT;
CREATE INDEX digest_lookup ON content_digests(algorithm,digest);
CREATE TABLE blob_content_map(object_id INTEGER PRIMARY KEY REFERENCES git_objects(id), content_id INTEGER NOT NULL REFERENCES contents(id), run_id TEXT NOT NULL REFERENCES collection_runs(id)) STRICT;
CREATE TABLE content_locations(content_id INTEGER NOT NULL REFERENCES contents(id), kind TEXT NOT NULL, locator TEXT NOT NULL, cache_id TEXT REFERENCES cache_entries(id), state TEXT NOT NULL, PRIMARY KEY(content_id,kind,locator)) STRICT;
CREATE TABLE root_manifests(tree_id INTEGER PRIMARY KEY REFERENCES git_objects(id), complete INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE root_manifest_entries(tree_id INTEGER NOT NULL REFERENCES root_manifests(tree_id), raw_path BLOB NOT NULL, mode INTEGER NOT NULL, object_id INTEGER REFERENCES git_objects(id), object_format TEXT NOT NULL, oid BLOB NOT NULL, PRIMARY KEY(tree_id,raw_path)) STRICT;
CREATE INDEX manifest_content ON root_manifest_entries(object_id,tree_id);
CREATE TABLE coverage_components(owner_id TEXT NOT NULL, kind TEXT NOT NULL, state TEXT NOT NULL, details TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(owner_id,kind)) STRICT;
CREATE TABLE pull_requests(id TEXT PRIMARY KEY, repo_id TEXT NOT NULL REFERENCES repositories(id), number INTEGER NOT NULL, node_id TEXT, current_observation INTEGER, UNIQUE(repo_id,number)) STRICT;
CREATE TABLE pr_observations(id INTEGER PRIMARY KEY, pr_id TEXT NOT NULL REFERENCES pull_requests(id), job_id TEXT NOT NULL REFERENCES jobs(id), observed_at TEXT NOT NULL, payload TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE pr_documents(id TEXT PRIMARY KEY, pr_id TEXT NOT NULL REFERENCES pull_requests(id), kind TEXT NOT NULL, provider_id TEXT NOT NULL, node_id TEXT, author TEXT, url TEXT, current_version INTEGER, deleted INTEGER NOT NULL DEFAULT 0, metadata TEXT NOT NULL DEFAULT '{}', UNIQUE(pr_id,kind,provider_id)) STRICT;
CREATE TABLE document_versions(id INTEGER PRIMARY KEY, document_id TEXT NOT NULL REFERENCES pr_documents(id), body TEXT NOT NULL, body_sha256 BLOB NOT NULL CHECK(length(body_sha256)=32), UNIQUE(document_id,body_sha256,body)) STRICT;
CREATE TABLE resource_observations(id INTEGER PRIMARY KEY, document_id TEXT NOT NULL REFERENCES pr_documents(id), version_id INTEGER NOT NULL REFERENCES document_versions(id), collection_run TEXT NOT NULL, observed_at TEXT NOT NULL, metadata TEXT NOT NULL, UNIQUE(collection_run,document_id)) STRICT;
CREATE TABLE pr_reviews(id TEXT PRIMARY KEY, pr_id TEXT NOT NULL REFERENCES pull_requests(id), document_id TEXT NOT NULL REFERENCES pr_documents(id), payload TEXT NOT NULL) STRICT;
CREATE TABLE review_threads(id TEXT PRIMARY KEY, pr_id TEXT NOT NULL REFERENCES pull_requests(id), payload TEXT NOT NULL, observed_at TEXT NOT NULL) STRICT;
CREATE TABLE review_comments(document_id TEXT PRIMARY KEY REFERENCES pr_documents(id), thread_id TEXT REFERENCES review_threads(id), payload TEXT NOT NULL) STRICT;
CREATE TABLE pr_events(id INTEGER PRIMARY KEY, pr_id TEXT NOT NULL REFERENCES pull_requests(id), run_id TEXT NOT NULL, ordinal INTEGER NOT NULL, provider_id TEXT, payload TEXT NOT NULL, UNIQUE(run_id,ordinal)) STRICT;
CREATE TABLE pr_code_observations(id INTEGER PRIMARY KEY, pr_id TEXT NOT NULL REFERENCES pull_requests(id), observation_id INTEGER NOT NULL REFERENCES pr_observations(id), head_oid TEXT, base_oid TEXT, state TEXT NOT NULL, details TEXT NOT NULL) STRICT;
CREATE TABLE pr_git_links(code_observation INTEGER NOT NULL REFERENCES pr_code_observations(id), role TEXT NOT NULL, object_format TEXT NOT NULL, oid BLOB NOT NULL, acquisition_id INTEGER REFERENCES acquisition_roots(id), PRIMARY KEY(code_observation,role,oid)) STRICT;
CREATE TABLE pr_commits(code_observation INTEGER NOT NULL REFERENCES pr_code_observations(id), ordinal INTEGER NOT NULL, oid TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(code_observation,ordinal)) STRICT;
CREATE TABLE pr_file_changes(code_observation INTEGER NOT NULL REFERENCES pr_code_observations(id), ordinal INTEGER NOT NULL, path TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(code_observation,ordinal)) STRICT;
CREATE TABLE api_responses(id INTEGER PRIMARY KEY, payload_sha256 BLOB NOT NULL, body BLOB NOT NULL, UNIQUE(payload_sha256,body)) STRICT;
CREATE TABLE collections(id TEXT PRIMARY KEY, pr_id TEXT REFERENCES pull_requests(id), repo_id TEXT NOT NULL REFERENCES repositories(id), kind TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id), state TEXT NOT NULL, scope TEXT NOT NULL, cursor TEXT, observed_at TEXT NOT NULL, reason TEXT) STRICT;
CREATE TABLE collection_pages(collection_id TEXT NOT NULL REFERENCES collections(id), ordinal INTEGER NOT NULL, response_id INTEGER NOT NULL REFERENCES api_responses(id), request TEXT NOT NULL, next_cursor TEXT, observed_at TEXT NOT NULL, PRIMARY KEY(collection_id,ordinal)) STRICT;
CREATE TABLE collection_memberships(collection_id TEXT NOT NULL REFERENCES collections(id), resource_id TEXT NOT NULL, ordinal INTEGER NOT NULL, PRIMARY KEY(collection_id,resource_id)) STRICT;
CREATE TABLE sync_checkpoints(scope TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE search_documents(id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('code','commits','pr')), source_key TEXT NOT NULL, body TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', UNIQUE(kind,source_key)) STRICT;
CREATE TABLE index_generations(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, state TEXT NOT NULL, table_name TEXT NOT NULL UNIQUE, target_max_id INTEGER NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE index_membership(generation_id INTEGER NOT NULL REFERENCES index_generations(id), document_id INTEGER NOT NULL REFERENCES search_documents(id), input_version TEXT NOT NULL, PRIMARY KEY(generation_id,document_id,input_version)) STRICT;
